# >>> STATIC
_static_f() {
    cat <<-'ARGCEOF'
	inet	for AF_INET
	inet6	for AF_INET6
	unix	for AF_UNIX
	vsock	for AF_VSOCK
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
_choice_interface() {
    if [[ "$ARGC_OS" == "linux" ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 -exec basename {} \;
    else
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}

_choice_protocol() {
    gawk '!/^#/ && NF { print $1 }' /etc/protocols 2>/dev/null
    echo bdg
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
